import unittest
import math
from candidate import factorize

class TestFactorize(unittest.TestCase):
    def test_factorize_single_prime(self):
        self.assertEqual(factorize(7), [7])

    def test_factorize_prime_power(self):
        self.assertEqual(factorize(81), [3, 3, 3, 3])

    def test_factorize_composite_with_repeats(self):
        self.assertEqual(factorize(72), [2, 2, 2, 3, 3])

    def test_factorize_small_composite(self):
        self.assertEqual(factorize(30), [2, 3, 5])

    def test_factorize_perfect_square(self):
        self.assertEqual(factorize(16), [2, 2, 2, 2])

    def test_factorize_single_factor(self):
        self.assertEqual(factorize(2), [2])

    def test_factorize_one_returns_empty(self):
        self.assertEqual(factorize(1), [])

    def test_factorize_zero_returns_empty(self):
        self.assertEqual(factorize(0), [])

    def test_factorize_product_matches_original(self):
        for n in [2, 3, 4, 6, 10, 12, 18, 30, 36, 72, 81, 100]:
            factors = factorize(n)
            prod = 1
            for f in factors:
                prod *= f
            self.assertEqual(prod, n)

    def test_factorize_order_ascending(self):
        self.assertEqual(factorize(70), [2, 5, 7])
        self.assertEqual(factorize(210), [2, 3, 5, 7])

    def test_factorize_large_prime(self):
        self.assertEqual(factorize(1013), [1013])

    def test_factorize_negative_raises_value_error(self):
        with self.assertRaises(ValueError):
            factorize(-10)

    def test_factorize_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            factorize(None)

    def test_factorize_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            factorize("15")

    def test_factorize_float_input(self):
        result = factorize(12.5)
        self.assertEqual(result, [12.5])

    def test_factorize_multiple_calls_consistent(self):
        first = factorize(60)
        second = factorize(60)
        self.assertEqual(first, second)

    def test_factorize_no_mutation_of_input(self):
        n = 98
        copy = n
        factorize(n)
        self.assertEqual(n, copy)

if __name__ == "__main__":
    unittest.main()
